head.script:
scwin.onpageload = function () {

};

/**
 * @method
 * @name addMinute
 * @description 입력된 날짜에 지정된 만큼의 분을 더한다.
 * @param {String} pYmd 날짜 형식의 문자열 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {Number} offset 더할 분 수
 * @returns {String} 지정된 offset만큼의 날짜가 더해진 날짜
 * @hidden N
 * @exception 
 * @example 
$c.date.addMinute("201708191210", 10); // "201708191220"
$c.date.addMinute("201708191210", -10); // "201708191200"
 */
scwin.addMinute = function (pYmd, offset) {
    return WebSquare.date.dateTimeAdd(pYmd, offset, "minute");
};


/**
 * @method
 * @name addHour
 * @description 입력된 날짜에 지정된 만큼의 시간을 더한다.
 * @param {String} pYmd 날짜 형식의 문자열 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {Number} offset 더할 시간 수.
 * @returns {String} 지정된 offset만큼의 날짜가 더해진 입력 날짜
 * @hidden N
 * @exception 
 * @example 
$c.date.addHour("2017081912", 10); // "2017081922"
$c.date.addHour("2017081912", -10); // "2017081902"
 */
scwin.addHour = function (pYmd, offset) {
    return WebSquare.date.dateTimeAdd(pYmd, offset, "hour");
};

/**
 * @method
 * @name addDate
 * @description 입력된 날짜에 지정된 만큼의 날을 더한다.
 * @param {String} pYmd 날짜 형식의 문자열 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {Number} offset 더할 날짜 수.
 * @returns {String} 지정된 offset만큼의 날짜가 더해진 입력 날짜
 * @hidden N
 * @exception 
 * @example 
$c.date.addDate("20170819", 2); // "20170821"
$c.date.addDate("20170819", -10); // "20170809"
 */
scwin.addDate = function (pYmd, offset) {
    return $c.date.isDate(pYmd) ? WebSquare.date.dateAdd(pYmd, offset) : "";
};

/**
 * @method
 * @name addMonth
 * @description 입력된 날짜에 지정된 만큼의 달을 더한다.
 * @param {String} pYmd 날짜 형식의 문자열 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {Number} offset 더할 개월 수.
 * @returns {String} 지정된 offset만큼의 개월이 더해진 입력 날짜
 * @hidden N
 * @exception 
 * @example
$c.date.addMonth("20170819", 2); // "20171019"
$c.date.addMonth("20170819", -10); // "20161019"
 */
scwin.addMonth = function (pYmd, offset) {
    try {
        let date = "";
        const isDate = $c.date.isDate(pYmd);

        if (!isDate) {
            return;
        }
        if (typeof offset == "undefined" || isNaN(offset)) {
            offset = 0;
        }

        let dY = (pYmd + "").substring(0, 4);
        let dM = (pYmd + "").substring(4, 6);
        let dD = (pYmd + "").substring(6, 8);
        let dTime = (pYmd + "").substring(8);
        dM = (dM * 1) + (offset * 1);

        if (dM > 0) {
            dY = (dY * 1) + Math.floor(dM / 12);
            dM = dM % 12;
        } else {
            dY = (dY * 1) - Math.floor((dM * -1 + 12) / 12);
            dM = dM % 12 + 12;
        }

        if (Number(dD) >= 30) {
            const chkMonth1 = [2];
            const chkMonth2 = [4, 6, 9, 11];

            if (chkMonth1.indexOf(dM) > -1) {
                if ($c.date.isLeafYear(dY + "01" + "01")) {
                    dD = "29";
                } else {
                    dD = "28";
                }
            } else if (chkMonth2.indexOf(dM) > -1) {
                if (Number(dD) > 30) {
                    dD = "30";
                }
            }
        }
        const cDate = new Date(dY, dM - 1, dD);
        const cYear = cDate.getFullYear();
        let cMonth = cDate.getMonth() + 1;
        if ((cMonth + "").length < 2) {
            cMonth = "0" + cMonth;
        }
        let cDay = cDate.getDate();
        if ((cDay + "").length < 2) {
            cDay = "0" + cDay;
        }
        date = cYear + "" + cMonth + "" + cDay + "" + dTime;
        return date;
    } catch (ex) {
        console.error(ex);
    }
};


/**
 * @method
 * @name getServerDateTime
 * @description 서버 날짜 반환한다. (default format: yyyyMMdd)
 * @param {String:N} sDateFormat 날짜 포맷
 * y Year 1996; 96
 * M Month in year 07
 * d Day in month 10
 * H Hour in day (0-23) 0
 * m Minute in hour 30
 * s Second in minute 55
 * S Millisecond 978
 * @returns {String} 현재날짜
 * @hidden N
 * @exception 
 * @example
$c.date.getServerDateTime("yyyy-MM-dd HH:mm:ss SSS");
$c.date.getServerDateTime("yyyy-MM-dd");
$c.date.getServerDateTime();
 */
scwin.getServerDateTime = function (sDateFormat) {
    if ($c.util.isEmpty(sDateFormat)) {
        sDateFormat = "yyyyMMdd";
    }

    return WebSquare.date.getCurrentServerDate(sDateFormat);
};

/**
 * @method
 * @name formatDate
 * @description 문자열에 날짜 Formatter를 적용하여 반환한다.
 * @param {String} str 포멧터를 적용할 파라메터 (String 또는 Number 타입 지원)
 * @param {String} type 적용할 포멧터 형식 Default:null,slash,date
 * @returns {String} 포멧터가 적용된 문자열
 * @hidden N
 * @exception 
 * @example
$c.date.formatDate(20120319, "slash"); 
// return 예시) 12/03/19

$c.date.formatDate(20120319, "date");
// return 예시) 2012/03/19

$c.date.formatDate(20120319, "colon");
// return 예시) 2012:03:19

$c.date.formatDate(20120319);
// return 예시) 2012년 03월 19일
 */
scwin.formatDate = function (str, type) {
    // 구 __formatDate($p 미전달용 내부 구현)를 병합 — $c 사용 함수는 공개 선언·$c 호출로 통일(빌드 $p 주입 규칙)
    if ($c.util.isEmpty(str)) return "";

    let output = "";
    let date = new String(str);

    if (type == "slash") {
        date = date.substring(2, date.length);
        for (let i = 0; i <= date.length - 1; i++) {
            output = output + date[i];
            if ((i + 1) % 2 == 0 && (date.length - 1) !== i)
                output = output + "/";
        }
    } else if (type == "date") {
        if (date.length == 8) {
            output = date.substring(0, 4) + "/" + date.substring(4, 6) + "/" + date.substring(6, 8);
        }
    } else if (type == "colon") {
        if (date.length == 8) {
            output = date.substring(0, 4) + ":" + date.substring(4, 6) + ":" + date.substring(6, 8);
        }
    } else if (!$c.util.isEmpty(type)) {
        if (date.length == 8) {
            output = date.substring(0, 4) + type + date.substring(4, 6) + type + date.substring(6, 8);
        }
    } else {
        const year = date.substring(0, 4);
        const month = date.substring(4, 6);
        const day = date.substring(6, 8);
        output = year + "년 " + month + "월 " + day + "일";
    }

    return output;
};


/**
 * @method
 * @name formatTime
 * @description 시간 - 입력된 String 또는 Number에 포메터를 적용하여 반환한다.
 * @param {String} value 시간 Formatter를 적용한 값 (String 또는 Number 타입 지원)
 * @returns {String} 포멧터가 적용된 문자열
 * @hidden N
 * @exception 
 * @example
$c.date.formatTime("123402");
// return 예시) "12:34:02"
 */
scwin.formatTime = function (value) {
    const hour = String(value).substring(0, 2);
    const minute = String(value).substring(2, 4);
    const second = String(value).substring(4, 6);
    return hour + ":" + minute + ":" + second;
};


/**
 * @method
 * @name formatDateTime
 * @description 날짜 객체에 포매팅을 적용한다. (default format: yyyyMMdd)
 * @param {Date} value 날짜 포맷팅을 적용할 날짜 객체
 * @param {String:N} sDateFormat 날짜 포맷
 * y Year 1996; 96
 * M Month in year 07
 * d Day in month 10
 * H Hour in day (0-23) 0
 * m Minute in hour 30
 * s Second in minute 55
 * S Millisecond 978
 * @returns {String} 현재날짜
 * @hidden N
 * @exception 
 * @example
$c.date.formatDateTime(new Date());  // "20190822"
$c.date.formatDateTime(new Date(), "yyyy-MM-dd HH:mm:ss SSS");  // "2019-08-22 15:55:35 705"
 */
scwin.formatDateTime = function (value, sDateFormat) {
    if ($c.util.isEmpty(sDateFormat)) {
        sDateFormat = "yyyyMMdd";
    }

    return WebSquare.date.getFormattedDate(value, sDateFormat);
};

/**
 * @method
 * @name isDate
 * @description 입력된 값이 Date 형식의 값인지 확인한다.
 * objName 을 전달하면 검증 실패 시 공통 메시지("$[0]에 올바른 날짜를 입력하세요.")로 $c.win.alert 를 호출한다.
 * @param {String|number} sDate 날짜 문자열 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {Boolean} timeChk 시간체크. (true/false)
 * @param {String} objName 메시지 출력 용 명칭 (값이 있으면 실패 시 알림)
 * @returns {Boolean} Date 형식에 일치하면 true, 아니면 false
 * @hidden N
 * @exception
 * @example
$c.date.isDate("20170819"); // return true
$c.date.isDate("20170832", false, "적용일"); // "적용일에 올바른 날짜를 입력하세요." 알림 후 return false
 */
scwin.isDate = function (sDate, timeChk, objName = "") {
    let flag = true;
    try {
        if (sDate.length == 8) {
            sDate = sDate + "000000";
        }

        const y1 = parseInt(sDate.substring(0, 4), 10);
        const m1 = parseInt(sDate.substring(4, 6), 10);
        const d1 = parseInt(sDate.substring(6, 8), 10);
        const h1 = parseInt(sDate.substring(8, 10), 10);
        const t1 = parseInt(sDate.substring(10, 12), 10);
        const s1 = parseInt(sDate.substring(12), 10);
        if (isNaN(y1) || isNaN(m1) || isNaN(d1) || isNaN(h1) || isNaN(t1) || isNaN(s1))
            flag = false;

        if (m1 < 1 || m1 > 12)
            flag = false;

        let maxDay = 31;
        if (m1 == 2) {
            maxDay = ((y1 % 400 == 0) || ((y1 % 4 == 0) && (y1 % 100 != 0))) ? 29
                : 28;
        } else if (m1 == 4 || m1 == 6 || m1 == 9 || m1 == 11) {
            maxDay = 30;
        }

        if (d1 < 1 || d1 > maxDay) {
            flag = false;
        }

        if (h1 + t1 + s1 != "") {
            if (h1 < 0 || h1 > 24) {
                flag = false;
            } else if (h1 == 24) {
                if (typeof timeChk == "boolean" && !timeChk)
                    flag = false;
                if (t1 > 0)
                    flag = false;
                if (s1 > 0)
                    flag = false;
            }
            if (t1 < 0 || t1 > 59)
                flag = false;
            if (s1 < 0 || s1 > 59)
                flag = false;
        }
    } catch (ex) {
        console.error(ex);
        flag = false;
    }

    // checkCalendarFormat 과 동일 규약 — objName 이 있으면 검증 실패 시 공통 메시지로 안내한다.
    // "com_valid_format_0052": "$[0]에 올바른 날짜를 입력하세요."
    if (!flag && $c.util.isEmpty(objName) === false) {
        $c.win.alert($c.data.getMessage("com_valid_format_0052", `${objName}`));
    }

    return flag;
};

/**
 * @method
 * @name diffDate
 * @description fromDate, toDate 를 입력받아 두 날짜의 차이를 반환한다.
 * @param {String} fromDate 시작일자 (date형식은 yyyyMMdd or yyyyMMddHHmmss)
 * @param {String} toDate 종료일자 (date형식은 yyyyMMdd or yyyyMMddHHmmss)
 * @returns {Number} 종료일자에서 시작일자의 날짜 차이 수.
 * @hidden N
 * @exception 
 * @example
$c.date.diffDate("20170821", "20180621"); // 304
 */
scwin.diffDate = function (fromDate, toDate) {
    try {
        if (!$c.date.isDate(fromDate) || !$c.date.isDate(toDate)) {
            return;
        }
        const diffDate = WebSquare.date.dateDiff(fromDate, toDate);
        return diffDate;
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name isLeafYear
 * @description 입력된 양력의 날짜가 윤년인지 검사한다.
 * @param {String} pYmd :: I :: Y ::  :: 윤달 확인 날짜.
 * @returns {Boolean} 윤달 유무( true : 윤달 )
 * @hidden N
 * @exception 
 * @example
$c.date.isLeafYear("20201212");  // return true
 */
scwin.isLeafYear = function (pYmd) {
    try {
        let isLeafYear = false;
        if (!$c.date.isDate(pYmd)) {
            return;
        } else {
            pYmd = pYmd.substring(0, 8);
            const y1 = parseInt(pYmd.substring(0, 4), 10);
            isLeafYear = ((y1 % 400 == 0) || ((y1 % 4 == 0) && (y1 % 100 != 0))) ? true : false;
        }
        return isLeafYear;
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name getDay
 * @description 특정 날짜의 요일을 반환한다.
 * @param {String} value "yyyyMMdd" 포맷 형태의 날짜를 나타내는 문자열 ("20190801")
 * @param {String} type 반환형식 기본값은 날짜를 한글로 반환 , num 인경우 숫자로 반환 일요일 :  1 ~ 토요일 : 7
 * @returns {String} 요일
 * @hidden N
 * @exception 
 * @example
$c.date.getDay("20190822");  // "목요일"
$c.date.getDay("20190824");  // "토요일"
 */
scwin.getDay = function (value, type) {
    let dayVal;
    if (type == "num") {
        dayVal = WebSquare.date._getDay(value);
        if (dayVal == 0) {
            return "7";
        } else {
            return String(dayVal);
        }
    } else {
        return WebSquare.date.getDay(value);
    }
};

/**
 * @method
 * @name getLunar
 * @description 특정 날짜의 음력 날짜를 반환한다.
 * @param {String} value "yyyyMMdd" 포맷 형태의 날짜를 나타내는 문자열
 * @returns {String} 음력 날짜
 * @hidden N
 * @exception 
 * @example
$c.date.getLunar("20190824");  // "20190724"
 */
scwin.getLunar = function (value) {
    return WebSquare.date.toLunar(value);
};

/**
 * @method
 * @name getLastDateOfMonth
 * @description 해당 월의 마지막 날짜를 반환한다.
 * @param {String} yearMonth 년월 문자열 (yyyyMM)
 * @returns 마지막 날짜
 * @hidden N
 * @exception 
 * @example
$c.date.getLastDateOfMonth("201510");  // 31
 */
scwin.getLastDateOfMonth = function (yearMonth) {
    try {
        if (typeof yearMonth !== "string") {
            yearMonth = $c.str.serialize(yearMonth);
        }

        const year = yearMonth.substring(0, 4);
        const month = yearMonth.substring(4, 6);

        return (new Date(year, month, 0)).getDate();
    } catch (ex) {
        console.error(ex);
        return null;
    }
};

// =============================================================================
// 추가 날짜 함수 (commonUtils.js 기준 정리)
// =============================================================================

/**
 * @method
 * @name addYear
 * @description 입력된 날짜에 지정된 만큼의 연도를 더한다.
 * @param {String} pYmd 날짜 형식의 문자열 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {Number} offset 더할 연도 수 (기본값 1)
 * @returns {String} 연도가 더해진 날짜
 * @hidden N
 * @exception
 * @example
$c.date.addYear("20220812", 2);  // "20240812"
$c.date.addYear("20220812", -1); // "20210812"
 */
scwin.addYear = function (pYmd, offset) {
    if (typeof offset === "undefined" || isNaN(offset)) {
        offset = 1;
    }
    return $c.date.addMonth(pYmd, Number(offset) * 12);
};

/**
 * @method
 * @name validateTime
 * @description 입력값이 HHmm 시간 형식(0000~2359)인지 검사한다.
 * @param {String} time 시간 문자열 (HHmm)
 * @returns {String} 유효하면 4자리 시간 문자열, 아니면 빈 문자열
 * @hidden N
 * @exception
 * @example
$c.date.validateTime("2319"); // "2319"
$c.date.validateTime("2419"); // ""
 */
scwin.validateTime = function (time) {
    if (!time) {
        return "";
    }
    const timePad = String(time).padEnd(4, "0");
    const regEx = /^([01]\d|2[0-3])?([0-5]\d)$/;
    return regEx.test(timePad) ? timePad : "";
};

/**
 * @method
 * @name diffTime
 * @description 두 일시의 시간(시) 차이를 반환한다.
 * @param {String} fromDate 시작일시 (yyyyMMdd or yyyyMMddHHmmss)
 * @param {String} toDate 종료일시 (yyyyMMdd or yyyyMMddHHmmss)
 * @returns {Number} 종료-시작 시간 차(시)
 * @hidden N
 * @exception
 * @example
$c.date.diffTime("20220106090000", "20220107090000"); // 24
 */
scwin.diffTime = function (fromDate, toDate) {
    try {
        if (!$c.date.isDate(fromDate) || !$c.date.isDate(toDate)) {
            return;
        }
        const toDateObj = function (ymd) {
            ymd = String(ymd);
            if (ymd.length === 8) {
                ymd += "000000";
            }
            return new Date(
                Number(ymd.substring(0, 4)),
                Number(ymd.substring(4, 6)) - 1,
                Number(ymd.substring(6, 8)),
                Number(ymd.substring(8, 10)),
                Number(ymd.substring(10, 12)),
                Number(ymd.substring(12, 14))
            );
        };
        const mSec = toDateObj(toDate).getTime() - toDateObj(fromDate).getTime();
        return Math.floor(mSec / (1000 * 60 * 60));
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name isBirth
 * @description 6자리 생년월일(YYMMDD)의 유효성을 검사한다.
 * @param {String} birthDay 6자리 생년월일 문자열
 * @returns {Boolean} 유효하면 true, 아니면 false
 * @hidden N
 * @exception
 * @example
$c.date.isBirth("071231"); // true
$c.date.isBirth("071331"); // false
 */
scwin.isBirth = function (birthDay) {
    const pattern = /^(?:[0-9]{2}(?:0[1-9]|1[0-2])(?:0[1-9]|[1,2][0-9]|3[0,1]))$/;
    if (!pattern.test(birthDay)) {
        return false;
    }
    const year = parseInt(birthDay.slice(0, 2), 10);
    const month = parseInt(birthDay.slice(2, 4), 10);
    const day = parseInt(birthDay.slice(4, 6), 10);
    const fullYear = 1900 + year;
    const date = new Date(fullYear, month - 1, day);
    return date.getFullYear() === fullYear && date.getMonth() === month - 1 && date.getDate() === day;
};

/**
 * @method
 * @name fromYmd
 * @description 날짜 문자열(yyyyMMddHHmmssSSS)을 Date 객체로 변환한다. (빈 값이면 현재 서버시각)
 * @param {String} ymd 날짜 문자열
 * @returns {Date} 변환된 Date 객체
 * @hidden N
 * @exception
 * @example
$c.date.fromYmd("20220304");       // Tue Mar 04 2022 00:00:00
$c.date.fromYmd("20220304135331"); // Fri Mar 04 2022 13:53:31
 */
scwin.fromYmd = function (ymd) {
    try {
        ymd = String(ymd == null ? "" : ymd);
        let len = ymd.length;
        if (len === 0) {
            ymd = $c.date.getServerDateTime("yyyyMMddHHmmssSSS");
            len = ymd.length;
        }
        const yy = Number(ymd.substring(0, 4));
        const MM = len >= 6 ? Number(ymd.substring(4, 6)) - 1 : 0;
        const dd = len >= 8 ? Number(ymd.substring(6, 8)) : 1;
        const hh = len >= 10 ? Number(ymd.substring(8, 10)) : 0;
        const mm = len >= 12 ? Number(ymd.substring(10, 12)) : 0;
        const ss = len >= 14 ? Number(ymd.substring(12, 14)) : 0;
        const SSS = len >= 17 ? Number(ymd.substring(14, 17)) : 0;
        return new Date(yy, MM, dd, hh, mm, ss, SSS);
    } catch (ex) {
        console.error(ex);
        return null;
    }
};

/**
 * @method
 * @name validatDate
 * @description 날짜 문자열(구분자 포함 가능)의 정합성을 검사한다. (1900년 이상, 말일 범위)
 * @param {String} str 날짜 문자열 (yyyyMMdd, yyyy-MM-dd 등)
 * @returns {Boolean} 유효하면 true, 아니면 false
 * @hidden N
 * @exception
 * @example
$c.date.validatDate("20220101"); // true
$c.date.validatDate("20220230"); // false
 */
scwin.validatDate = function (str) {
    const strDt = String(str).replace(/[^\d]/g, "").replace(/(\d{4})(\d{2})(\d{2})/, "$1-$2-$3");
    if (strDt.length !== 10) {
        return false;
    }
    if (isNaN(Date.parse(strDt))) {
        return false;
    }
    const arrDt = strDt.split("-");
    if (Number(arrDt[0]) < 1900) {
        return false;
    }
    const dt = new Date(arrDt[0], arrDt[1], 0);
    if (Number(arrDt[2]) > dt.getDate()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name validatYearMonth
 * @description 연월 문자열(yyyyMM, 구분자 포함 가능)의 정합성을 검사한다.
 * @param {String} str 연월 문자열
 * @returns {Boolean} 유효하면 true, 아니면 false
 * @hidden N
 * @exception
 * @example
$c.date.validatYearMonth("202201"); // true
$c.date.validatYearMonth("202213"); // false
 */
scwin.validatYearMonth = function (str) {
    let strDt = String(str).replace(/[^\d]/g, "").replace(/(\d{4})(\d{2})/, "$1-$2");
    if (strDt.length !== 7) {
        return false;
    }
    strDt += "-01";
    if (isNaN(Date.parse(strDt))) {
        return false;
    }
    const arrDt = strDt.split("-");
    if (Number(arrDt[0]) < 1900) {
        return false;
    }
    const dt = new Date(arrDt[0], arrDt[1], 0);
    if (Number(arrDt[2]) > dt.getDate()) {
        return false;
    }
    return true;
};

// =============================================================================
// 추가 날짜 함수 (commonUtils.js 기준 정리 — 2차)
// =============================================================================

/**
 * @method
 * @name addMonthCal
 * @description 월말 보정 방식으로 입력 날짜에 지정 개월을 가감한다. (입력이 말일이면 결과도 말일/01)
 * @param {String} pYmd 날짜 문자열 (yyyyMMdd)
 * @param {Number} offset 가감할 개월 수
 * @returns {String} 개월이 가감된 날짜 (yyyyMMdd)
 * @hidden N
 * @exception
 * @example
$c.date.addMonthCal("20170819", 2);   // "20171019"
$c.date.addMonthCal("20220228", 1);   // "20220331" (말일 보정)
 */
scwin.addMonthCal = function (pYmd, offset) {
    try {
        if (typeof offset === "undefined" || isNaN(offset)) {
            offset = 0;
        }
        offset = Number.parseInt(offset);

        const year = parseInt(pYmd.substring(0, 4));
        const month = parseInt(pYmd.substring(4, 6)) - 1; // Date 월은 0-based
        const day = parseInt(pYmd.substring(6, 8));

        // 입력일이 해당 월의 말일인지 판정
        const lastOfInput = new Date(year, month + 1, 0).getDate();
        const isLastDate = (day === lastOfInput);

        // 대상 월의 말일
        const target = new Date(year, month + offset, 1);
        const lastOfTarget = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate();

        // 말일 입력이면 대상 월의 말일로, 아니면 같은 일(대상 월 말일로 클램핑)
        const resultDay = isLastDate ? lastOfTarget : Math.min(day, lastOfTarget);
        const result = new Date(target.getFullYear(), target.getMonth(), resultDay);

        const pad = function (n) { return String(n).padStart(2, "0"); };
        return `${result.getFullYear()}${pad(result.getMonth() + 1)}${pad(result.getDate())}`;
    } catch (ex) {
        console.error(ex);
    }
};

/**
 * @method
 * @name addYmd
 * @description 날짜 문자열의 특정 구성요소(Y/M/D/h/m/s)에 offset을 가감한다. (입력 자릿수 유지)
 * @param {String} pYmd 날짜 문자열 (yyyyMMdd[HHmmss])
 * @param {Number} offset 증감분 (기본값 1)
 * @param {String} ymdSe 구성요소 "Y"|"M"|"D"|"h"|"m"|"s" (기본값 "D")
 * @returns {String} 가감된 날짜 문자열 (입력과 동일 자릿수)
 * @hidden N
 * @exception
 * @example
$c.date.addYmd("20220812", 2);       // "20220814" (기본 단위 "D" = 일)
$c.date.addYmd("20220812", -1, "Y"); // "20210812"
$c.date.addYmd("20220812", 1, "M");  // "20220912"
 */
scwin.addYmd = function (pYmd, offset, ymdSe) {
    offset = (offset == null || isNaN(offset)) ? 1 : Number(offset);
    ymdSe = ymdSe || "D";
    const idx = ["Y", "M", "D", "h", "m", "s"].indexOf(ymdSe);
    if (idx < 0) {
        return pYmd;
    }
    const digits = String(pYmd).replace(/[^0-9]/g, "");
    const parts = [
        digits.substring(0, 4), digits.substring(4, 6), digits.substring(6, 8),
        digits.substring(8, 10), digits.substring(10, 12), digits.substring(12, 14)
    ].filter(function (s) { return s !== ""; }).map(Number);
    if (idx >= parts.length) {
        return pYmd;
    }
    if (parts.length > 1) {
        parts[1] -= 1; // Date 월은 0-based
    }
    parts[idx] += offset;
    const d = new Date(parts[0], parts[1] || 0, parts[2] || 1, parts[3] || 0, parts[4] || 0, parts[5] || 0);
    const pad = function (n, l) { return String(n).padStart(l, "0"); };
    const full = pad(d.getFullYear(), 4) + pad(d.getMonth() + 1, 2) + pad(d.getDate(), 2) +
        pad(d.getHours(), 2) + pad(d.getMinutes(), 2) + pad(d.getSeconds(), 2);
    return full.substring(0, digits.length);
};

/**
 * @method
 * @name dateFormat
 * @description Date 객체를 지정 포맷 문자열로 변환한다. ($c.date.formatDateTime 위임)
 * @param {Date} date 변환할 Date 객체
 * @param {String} format 포맷 (기본값 "yyyyMMdd")
 * @returns {String} 포맷이 적용된 문자열
 * @hidden N
 * @exception
 * @example
$c.date.dateFormat(new Date(), "yyyy-MM-dd HH:mm:ss");
 */
scwin.dateFormat = function (date, format) {
    return $c.date.formatDateTime(date, format);
};

/**
 * @method
 * @name dateUnFormat
 * @description 포맷된 날짜 문자열에서 구분자 등 비숫자 문자를 모두 제거해 숫자 문자열로 반환한다.
 * @param {String} dateStr 포맷된 날짜 문자열
 * @returns {String} 숫자만 남긴 문자열
 * @hidden N
 * @exception
 * @example
$c.date.dateUnFormat("2022/08/04");          // "20220804"
$c.date.dateUnFormat("2022-08-04 13:53:31"); // "20220804135331"
 */
scwin.dateUnFormat = function (dateStr) {
    return String(dateStr).replace(/[^0-9]/g, "");
};

/**
 * @method
 * @name getDateInterval
 * @description 두 날짜의 간격을 지정 단위(Y/M/D/h/m/s)로 반환한다.
 * @param {String|Date} fromVal 시작 일자
 * @param {String|Date} toVal 종료 일자
 * @param {String} ymdType 단위 (기본값 "D"). Y/M/D/h/m/s — "m"은 분, "M"은 월(대소문자 구분).
 * 별칭 허용: DAY·DD(일), MONTH·MON·MM(월), YEAR·YYYY·YY(년), HH·H(시), MI(분), SS·S(초)
 * @returns {Number} 간격 (단위 기준), 날짜 변환 실패 또는 알 수 없는 단위이면 null
 * @hidden N
 * @exception
 * @example
$c.date.getDateInterval("2022/08/04", "2022/08/31");      // 27
$c.date.getDateInterval("2021/08/04", "2022/08/31", "Y"); // ≈1.07
 */
scwin.getDateInterval = function (fromVal, toVal, ymdType) {
    ymdType = ymdType || "D";
    const dateFmtData = { Y: 60 * 60 * 24 * 365, M: 60 * 60 * 24 * 30, D: 60 * 60 * 24, h: 60 * 60, m: 60, s: 1 };
    if (dateFmtData[ymdType] == null) {
        const u = String(ymdType).toUpperCase();
        if (["DAY", "D", "DD"].includes(u)) { ymdType = "D"; }
        else if (["MONTH", "MON", "MM", "M"].includes(u)) { ymdType = "M"; }
        else if (["YEAR", "YYYY", "YY", "Y"].includes(u)) { ymdType = "Y"; }
        else if (["HH", "H"].includes(u)) { ymdType = "h"; }
        else if (["MI"].includes(u)) { ymdType = "m"; }
        else if (["SS", "S"].includes(u)) { ymdType = "s"; }
        else { return null; }
    }

    let fromDate, toDate;
    if (typeof fromVal === "string" && $c.date.validatDate(fromVal)) { fromDate = $c.date.fromYmd(fromVal.replace(/[^0-9]/g, "")); }
    else if (fromVal instanceof Date) { fromDate = fromVal; }
    if (typeof toVal === "string" && $c.date.validatDate(toVal)) { toDate = $c.date.fromYmd(toVal.replace(/[^0-9]/g, "")); }
    else if (toVal instanceof Date) { toDate = toVal; }

    if (fromDate == null || toDate == null) {
        return null;
    }
    return (toDate - fromDate) / dateFmtData[ymdType] / 1000;
};

/**
 * @method
 * @name dateCompare
 * @description 두 날짜를 비교한다. toVal이 fromVal보다 같거나 크면 true.
 * @param {String|Date} fromVal 시작 일자
 * @param {String|Date} toVal 종료 일자
 * @param {String} ymdType 비교 단위 (기본값 "s")
 * @returns {Boolean} toVal >= fromVal 이면 true
 * @hidden N
 * @exception
 * @example
$c.date.dateCompare("2022/08/04", "2022/08/31"); // true
$c.date.dateCompare("2022/08/31", "2021/08/04"); // false
 */
scwin.dateCompare = function (fromVal, toVal, ymdType) {
    const diff = $c.date.getDateInterval(fromVal, toVal, ymdType || "s");
    if (diff == null) {
        return false;
    }
    return (diff < 0 ? Math.ceil(diff) : Math.floor(diff)) >= 0;
};

/**
 * @method
 * @name getWeekStartEndDay
 * @description 특정 일자가 속한 주의 시작일(월)·종료일(일)을 반환한다.
 * @param {String|Date} dateVal 기준 일자 (생략 시 서버 현재일)
 * @returns {Object} { startDay, endDay } (yyyyMMdd)
 * @hidden N
 * @exception
 * @example
$c.date.getWeekStartEndDay("2022/08/04"); // {startDay:"20220801", endDay:"20220807"}
 */
scwin.getWeekStartEndDay = function (dateVal) {
    if ($c.util.isEmpty(dateVal)) {
        dateVal = $c.date.fromYmd($c.date.getServerDateTime("yyyyMMdd"));
    }
    let date;
    if (typeof dateVal === "string" && $c.date.validatDate(dateVal)) {
        date = $c.date.fromYmd(dateVal.replace(/[^0-9]/g, ""));
    } else if (dateVal instanceof Date) {
        date = dateVal;
    } else {
        return null;
    }
    const day = date.getDay();
    const addCnt = day === 0 ? -6 : -(day - 1);
    const base = $c.date.formatDateTime(date, "yyyyMMdd");
    return {
        startDay: $c.date.addYmd(base, addCnt),
        endDay: $c.date.addYmd(base, addCnt + 6)
    };
};

/**
 * @method
 * @name checkDateFormat
 * @description 날짜 문자열이 지정 포맷과 일치하고 실제 존재하는 유효한 날짜인지 검증한다.
 * (연 4자리, 월 2자리, 일 2자리 기준. 구분자 위치·숫자 여부·월/일 실존 여부를 검사)
 * checkCalendarFormat / compareFromToDate 가 공유하는 내부 검증 로직이다.
 * @param {String} value 검증할 날짜 문자열
 * @param {String} dateFormat 검증 포맷 (예: "yyyyMMdd", "yyyy-MM-dd", "yyyy/MM/dd", "yyyy.MM.dd")
 * @returns {Boolean} 포맷·유효성 만족 여부
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDateFormat = function (value, dateFormat) {
    value = String(value);

    if ($c.util.isEmpty(dateFormat) || typeof dateFormat !== "string") {
        return false;
    }

    // 빈 값이면 실패 처리 — 필수 여부는 업무 규칙에 따라 별도 판단
    if ($c.util.isEmpty(value.trim())) {
        return false;
    }

    // 길이 검증 (포맷 길이와 값 길이 일치)
    if (value.length !== dateFormat.length) {
        return false;
    }

    // 위치별 검증 (구분자 위치는 동일 문자, y/M/d 위치는 숫자) 및 연/월/일 추출
    let yearStr = "", monthStr = "", dayStr = "";
    for (let i = 0; i < dateFormat.length; i++) {
        const fmtChar = dateFormat.charAt(i);
        const valChar = value.charAt(i);

        if (fmtChar === "y") {
            yearStr += valChar;
        } else if (fmtChar === "M") {
            monthStr += valChar;
        } else if (fmtChar === "d") {
            dayStr += valChar;
        } else {
            // 구분자 위치 : 포맷과 값이 동일해야 함
            if (fmtChar !== valChar) {
                return false;
            }
            continue;
        }

        // y/M/d 위치 : 숫자만 허용
        if (valChar === " " || isNaN(valChar)) {
            return false;
        }
    }

    // 자릿수 검증 (연 4자리, 월 2자리, 일 2자리)
    if (yearStr.length !== 4 || monthStr.length !== 2 || dayStr.length !== 2) {
        return false;
    }

    const year = parseInt(yearStr, 10);
    const month = parseInt(monthStr, 10);
    const day = parseInt(dayStr, 10);

    // 월 범위 검증
    if (month < 1 || month > 12) {
        return false;
    }

    // 실존 날짜 검증 (예: 2026-02-31 방지)
    const dateObj = new Date(year, month - 1, day);
    if (dateObj.getFullYear() !== year || dateObj.getMonth() + 1 !== month || dateObj.getDate() !== day) {
        return false;
    }

    return true;
};

/**
 * @method
 * @name compareFromToDate
 * @description 시작일·종료일 inputCalendar 컴포넌트의 기간 유효성을 검증하고 위반 시 안내 후 날짜를 동기화한다.
 * 시작일 변경(onviewchange) 시 시작일 > 종료일이면 안내 후 시작일을 종료일로 원복한다.
 * 종료일 변경(onviewchange) 시 종료일 < 시작일이면 안내 후 종료일을 시작일로 원복한다.
 * dateFormat 을 지정하면 변경된 값이 해당 포맷·실존 날짜인지 먼저 검증하고, 불일치 시 안내 후 기간 비교를 건너뛴다.
 * @param {Object} calStartDate 시작일 inputCalendar 컴포넌트 객체
 * @param {Object} calEndDate 종료일 inputCalendar 컴포넌트 객체
 * @param {Array} msgOptions 메시지 치환 명칭 배열 [시작일 명칭, 종료일 명칭] (기본값 ["검색시작일", "검색종료일"])
 * @param {String} dateFormat 날짜 포맷 검증값 (예: "yyyyMMdd", "yyyy-MM-dd"). 생략 시 포맷 검증 미수행.
 * @returns {void}
 * @hidden N
 * @exception
 * @example
// 기본 메시지 사용
$c.date.compareFromToDate(cal_start1, cal_end1);
// 사용자 정의 명칭 지정
$c.date.compareFromToDate(cal_start2, cal_end2, ["조회 시작일자", "조회 종료일자"]);
// 날짜 포맷 검증 추가
$c.date.compareFromToDate(cal_start3, cal_end3, ["조회 시작일자", "조회 종료일자"], "yyyy-MM-dd");
 */
scwin.compareFromToDate = function (calStartDate, calEndDate, msgOptions, dateFormat) {
    if ($c.util.isEmpty(calStartDate) || $c.util.isEmpty(calEndDate)) {
        console.error("[compareFromToDate] 필수 인자(calStartDate, calEndDate)가 누락되었습니다.");
        return;
    }

    if (!Array.isArray(msgOptions) || msgOptions.length < 2) {
        msgOptions = ["검색시작일", "검색종료일"];
    }
    const startLabel = msgOptions[0];
    const endLabel = msgOptions[1];

    // 명칭 뒤에 받침 유무에 따라 "을/를"을 붙여 반환한다.
    const withJosa = function (label) {
        return label + ($c.str.isFinalConsonant(String(label)) ? "을" : "를");
    };

    // dateFormat 지정 시 : 값이 포맷·실존 날짜가 아니면 안내하고 true 반환(비교 건너뜀 신호).
    const isFormatInvalid = async function (value) {
        if ($c.util.isEmpty(dateFormat) || $c.util.isEmpty(value)) {
            return false;
        }
        if (!$c.date.checkDateFormat(value, dateFormat)) {   // 공개 함수 내부 호출도 $c 경유 — 빌드 $p 주입 규칙
            await $c.win.alert(dateFormat + " 형식의 올바른 날짜를 입력하세요.");
            return true;
        }
        return false;
    };

    // 시작일 변경 시 : 시작일 > 종료일이면 안내 후 시작일을 종료일로 원복한다.
    calStartDate.unbind("onviewchange");
    calStartDate.bind("onviewchange", async function (info) {
        const startVal = calStartDate.getValue();
        const endVal = calEndDate.getValue();
		if (await isFormatInvalid(startVal)) {
			calStartDate.focus();
            return;
        }
        if (!$c.util.isEmpty(startVal) && !$c.util.isEmpty(endVal) && startVal > endVal) {
			console.log("calStartDate.setUserData();");
			calStartDate.setUserData("onkeyup", false);
            await $c.win.alert(withJosa(startLabel) + " " + endLabel + " 이전으로 선택하세요.");
            calStartDate.setValue(endVal);
			calStartDate.setUserData("onkeyup", true);
        }
    });

    // 종료일 변경 시 : 종료일 < 시작일이면 안내 후 종료일을 시작일로 원복한다.
    calEndDate.unbind("onviewchange");
    calEndDate.bind("onviewchange", async function (info) {
        const startVal = calStartDate.getValue();
        const endVal = calEndDate.getValue();
        if (await isFormatInvalid(endVal)) {
			calEndDate.focus();
            return;
        }		
        if (!$c.util.isEmpty(startVal) && !$c.util.isEmpty(endVal) && endVal < startVal) {
			calEndDate.setUserData("onkeyup", false);
            await $c.win.alert(withJosa(endLabel) + " " + startLabel + " 이후로 선택하세요.");
            calEndDate.setValue(startVal);
			calEndDate.setUserData("onkeyup", true);
        }
    });	
};

/**
 * @method
 * @name checkCalendarFormat
 * @description inputCalendar 컴포넌트의 입력값이 지정한 포맷과 일치하고 실제 존재하는 유효한 날짜인지 검증한다.
 * (연 4자리, 월 2자리, 일 2자리 기준. 구분자 위치·숫자 여부·월/일 실존 여부를 검사)
 * @param {Object|String} calendarObj inputCalendar 컴포넌트 객체 또는 컴포넌트 ID
 * @param {String} dateFormat 검증할 날짜 포맷 (예: "yyyyMMdd", "yyyy-MM-dd", "yyyy/MM/dd", "yyyy.MM.dd")
 * @param {String} objName 메시지 출력 용 명칭
 * @returns {Boolean} 포맷·유효성 만족 여부 (true: 정상, false: 오류)
 * @hidden N
 * @exception
 * @example
$c.date.checkCalendarFormat(ica_startDate, "yyyy-MM-dd"); // 컴포넌트 객체 전달
$c.date.checkCalendarFormat("ica_endDate", "yyyyMMdd");   // 컴포넌트 ID 전달
 */
scwin.checkCalendarFormat = function (calendarObj, dateFormat, objName = "") {
    // 1. 컴포넌트 객체 확보 및 유효성 검사
    const comp = (typeof calendarObj === "string") ? $p.getComponentById(calendarObj) : calendarObj;
    if ($c.util.isEmpty(comp) || typeof comp.getValue !== "function") {
        console.error("[checkCalendarFormat] 올바른 inputCalendar 객체나 ID를 전달해야 합니다.");
        return false;
    }
    if ($c.util.isEmpty(dateFormat) || typeof dateFormat !== "string") {
        console.error("[checkCalendarFormat] dateFormat 문자열이 필요합니다.");
        return false;
    }

    // 입력값이 포맷과 일치하고 실제 존재하는 유효한 날짜인지 검증한다. (공통 검증 로직 재사용)
    const isValidFormat = function () {
        return $c.date.checkDateFormat(comp.getValue(), dateFormat);   // 공개 함수 내부 호출도 $c 경유 — 빌드 $p 주입 규칙
    };

    // compareFromToDate 와 같이 onviewchange 이벤트에서 검증 실패 시 $c.win.alert 로 안내한다.
    comp.unbind("onviewchange");
    comp.bind("onviewchange", function () {
        if (!isValidFormat()) {
	            // "com_valid_format_0051": "$[0] 형식의 올바른 날짜를 입력하세요.",  "com_valid_format_0052": "$[0]에 올바른 날짜를 입력하세요.",
            const msg = ($c.util.isEmpty(objName)) ? $c.data.getMessage("com_valid_format_0051", `${dateFormat}`) : $c.data.getMessage("com_valid_format_0052", `${objName}`);
            $c.win.alert(msg);
        }
    });

    return isValidFormat();
};
